//! Bit-exactness tests against vectors generated by the real LuaJIT
//! (tools/gen_rng_vectors.lua). Regenerate with:
//!   luajit tools/gen_rng_vectors.lua > sim/core/tests/data/rng_vectors.tsv

use std::collections::HashMap;

use balatro_core::rng::{pseudohash, LuaRandom, RngState};

const VECTORS: &str = include_str!("data/rng_vectors.tsv");

fn parse_bits(s: &str) -> u64 {
    u64::from_str_radix(s, 16).unwrap()
}

fn assert_bits_eq(got: f64, want_bits: u64, ctx: &str) {
    let want = f64::from_bits(want_bits);
    if got.is_nan() && want.is_nan() {
        return; // NaN payloads may differ across float pipelines; NaN==NaN is enough
    }
    assert_eq!(
        got.to_bits(),
        want_bits,
        "{ctx}: got {got:?} ({:016x}), want {want:?} ({want_bits:016x})",
        got.to_bits()
    );
}

#[test]
fn matches_luajit_vectors() {
    let mut streams: HashMap<String, RngState> = HashMap::new();
    let mut counts = [0usize; 4];

    for line in VECTORS.lines() {
        let f: Vec<&str> = line.split('\t').collect();
        match f[0] {
            "pseudohash" => {
                assert_bits_eq(
                    pseudohash(f[1]),
                    parse_bits(f[2]),
                    &format!("pseudohash({:?})", f[1]),
                );
                counts[0] += 1;
            }
            "pseudoseed" => {
                let (seed, key, call) = (f[1], f[2], f[3]);
                let state = streams
                    .entry(seed.to_string())
                    .or_insert_with(|| RngState::new(seed));
                let got = state.pseudoseed(key);
                assert_bits_eq(
                    got,
                    parse_bits(f[4]),
                    &format!("pseudoseed({seed:?}, {key:?}) call {call}"),
                );
                counts[1] += 1;
            }
            "random" => {
                let seed = f64::from_bits(parse_bits(f[1]));
                let mut r = LuaRandom::seeded(seed);
                for (i, want) in f[2].split(',').enumerate() {
                    assert_bits_eq(
                        r.random(),
                        parse_bits(want),
                        &format!("random(seed={seed}) draw {i}"),
                    );
                }
                counts[2] += 1;
            }
            "randint" => {
                let seed = f64::from_bits(parse_bits(f[1]));
                let (m, n): (i64, i64) = (f[2].parse().unwrap(), f[3].parse().unwrap());
                let mut r = LuaRandom::seeded(seed);
                for (i, want) in f[4].split(',').enumerate() {
                    let got = r.random_range(m, n);
                    assert_eq!(
                        got,
                        want.parse::<i64>().unwrap(),
                        "randint(seed={seed},{m},{n}) draw {i}"
                    );
                }
                counts[3] += 1;
            }
            "randint1" => {
                // math.random(n) == math.random(1, n)
                let seed = f64::from_bits(parse_bits(f[1]));
                let n: i64 = f[2].parse().unwrap();
                let mut r = LuaRandom::seeded(seed);
                for (i, want) in f[3].split(',').enumerate() {
                    let got = r.random_range(1, n);
                    assert_eq!(
                        got,
                        want.parse::<i64>().unwrap(),
                        "randint1(seed={seed},{n}) draw {i}"
                    );
                }
                counts[3] += 1;
            }
            other => panic!("unknown vector type {other:?}"),
        }
    }

    // Guard against silently passing on an empty/truncated vector file.
    assert!(counts[0] >= 100, "pseudohash vectors: {}", counts[0]);
    assert!(counts[1] >= 400, "pseudoseed vectors: {}", counts[1]);
    assert!(counts[2] >= 10, "random vectors: {}", counts[2]);
    assert!(counts[3] >= 20, "randint vectors: {}", counts[3]);
}
